#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <string.h>

static inline void radix_sort_i64(int64_t *a, size_t n) {
    if (n <= 1) return;
    uint64_t *u = (uint64_t *)a;
    uint64_t *tmp = (uint64_t *)malloc(n * sizeof(uint64_t));
    if (!tmp) return;

    uint64_t min_u = u[0] ^ 0x8000000000000000ULL;
    uint64_t max_u = min_u;
    for (size_t i = 0; i < n; i++) {
        uint64_t v = u[i] ^ 0x8000000000000000ULL;
        u[i] = v;
        if (v < min_u) min_u = v;
        if (v > max_u) max_u = v;
    }
    uint64_t diff = min_u ^ max_u;

    uint64_t *src = u;
    uint64_t *dst = tmp;

    for (int shift = 0; shift < 64; shift += 8) {
        if (((diff >> shift) & 0xFF) == 0) continue;
        size_t count[256] = {0};
        for (size_t i = 0; i < n; i++) {
            count[(src[i] >> shift) & 0xFF]++;
        }
        size_t pref[256];
        size_t sum = 0;
        for (int b = 0; b < 256; b++) {
            pref[b] = sum;
            sum += count[b];
        }
        for (size_t i = 0; i < n; i++) {
            uint64_t v = src[i];
            dst[pref[(v >> shift) & 0xFF]++] = v;
        }
        uint64_t *swap = src;
        src = dst;
        dst = swap;
    }

    for (size_t i = 0; i < n; i++) {
        u[i] = src[i] ^ 0x8000000000000000ULL;
    }
    free(tmp);
}

static char DIGITS_LUT[200];
static int lut_init = 0;
static void init_lut(void) {
    if (lut_init) return;
    for (int i = 0; i < 100; i++) {
        DIGITS_LUT[2 * i] = (char)('0' + (i / 10));
        DIGITS_LUT[2 * i + 1] = (char)('0' + (i % 10));
    }
    lut_init = 1;
}

static inline char *format_i64(char *p, int64_t val) {
    uint64_t u;
    if (val < 0) {
        *p++ = '-';
        u = (uint64_t)(-(val + 1)) + 1ULL;
    } else {
        u = (uint64_t)val;
    }
    char buf[24];
    char *end = buf + 24;
    char *cur = end;
    while (u >= 100) {
        unsigned int rem = (unsigned int)(u % 100);
        u /= 100;
        cur -= 2;
        cur[0] = DIGITS_LUT[2 * rem];
        cur[1] = DIGITS_LUT[2 * rem + 1];
    }
    if (u < 10) {
        *--cur = (char)('0' + u);
    } else {
        cur -= 2;
        cur[0] = DIGITS_LUT[2 * u];
        cur[1] = DIGITS_LUT[2 * u + 1];
    }
    size_t len = (size_t)(end - cur);
    memcpy(p, cur, len);
    p += len;
    *p++ = '\n';
    return p;
}

int fastsort_main(void) {
    init_lut();
    struct stat st;
    char *in_buf = NULL;
    size_t in_len = 0;
    int is_mmap = 0;

    if (fstat(0, &st) == 0 && S_ISREG(st.st_mode) && st.st_size > 0) {
        in_len = (size_t)st.st_size;
        void *m = mmap(NULL, in_len, PROT_READ, MAP_PRIVATE, 0, 0);
        if (m != MAP_FAILED) {
            in_buf = (char *)m;
            is_mmap = 1;
        }
    }
    if (!in_buf) {
        size_t cap = 65536;
        in_buf = (char *)malloc(cap);
        if (!in_buf) return -1;
        while (1) {
            if (in_len == cap) {
                cap *= 2;
                char *nb = (char *)realloc(in_buf, cap);
                if (!nb) { free(in_buf); return -1; }
                in_buf = nb;
            }
            ssize_t r = read(0, in_buf + in_len, cap - in_len);
            if (r < 0) { free(in_buf); return -1; }
            if (r == 0) break;
            in_len += (size_t)r;
        }
    }

    size_t cap_ints = (in_len / 6) + 1024;
    int64_t *arr = (int64_t *)malloc(cap_ints * sizeof(int64_t));
    if (!arr) {
        if (is_mmap) munmap(in_buf, in_len); else free(in_buf);
        return -1;
    }

    size_t n = 0;
    const unsigned char *p = (const unsigned char *)in_buf;
    const unsigned char *end = p + in_len;

    while (p < end) {
        while (p < end && *p <= ' ') p++;
        if (p >= end) break;
        int neg = 0;
        if (*p == '-') {
            neg = 1;
            p++;
        } else if (*p == '+') {
            p++;
        }
        if (p >= end || *p < '0' || *p > '9') {
            free(arr);
            if (is_mmap) munmap(in_buf, in_len); else free(in_buf);
            return -1;
        }
        uint64_t acc = 0;
        int digits = 0;
        while (p < end && *p >= '0' && *p <= '9') {
            acc = acc * 10 + (*p - '0');
            p++;
            digits++;
            if (digits > 19) {
                free(arr);
                if (is_mmap) munmap(in_buf, in_len); else free(in_buf);
                return -1;
            }
        }
        if (digits == 19) {
            uint64_t limit = neg ? 9223372036854775808ULL : 9223372036854775807ULL;
            if (acc > limit) {
                free(arr);
                if (is_mmap) munmap(in_buf, in_len); else free(in_buf);
                return -1;
            }
        }
        if (n == cap_ints) {
            cap_ints *= 2;
            int64_t *na = (int64_t *)realloc(arr, cap_ints * sizeof(int64_t));
            if (!na) {
                free(arr);
                if (is_mmap) munmap(in_buf, in_len); else free(in_buf);
                return -1;
            }
            arr = na;
        }
        arr[n++] = neg ? (int64_t)(-acc) : (int64_t)acc;
    }

    if (is_mmap) munmap(in_buf, in_len); else free(in_buf);

    radix_sort_i64(arr, n);

    size_t out_cap = n * 21 + 64;
    char *out_buf = (char *)malloc(out_cap);
    if (!out_buf) {
        free(arr);
        return -1;
    }
    char *out_p = out_buf;
    for (size_t i = 0; i < n; i++) {
        out_p = format_i64(out_p, arr[i]);
    }
    free(arr);

    size_t total_out = (size_t)(out_p - out_buf);
    size_t written = 0;
    while (written < total_out) {
        ssize_t w = write(1, out_buf + written, total_out - written);
        if (w <= 0) {
            free(out_buf);
            return -1;
        }
        written += (size_t)w;
    }
    free(out_buf);
    return 0;
}
